}

drills.solution:
export async function listOrdersWithCustomers(db) {
  const orders = await db.listOrders();
  const ids = [...new Set(orders.map((o) => o.customerId))];
  const byId = new Map();
  if (ids.length > 0) {
    for (const c of await db.customersByIds(ids)) byId.set(c.id, c);
  }
  return orders.map((o) => ({
    id: o.id,
    total: o.total,
    customerName: byId.get(o.customerId)?.name ?? null,
  }));
}

