drills.solution:
export function createLoader(batchFn) {
  let pending = null;

  const dispatch = async (batch) => {
    const keys = [...batch.keys()];
    let values;
    try {
      values = await batchFn(keys);
      if (!Array.isArray(values) || values.length !== keys.length) {
        throw new Error(`batch function returned ${values?.length} values for ${keys.length} keys`);
      }
    } catch (err) {
      for (const d of batch.values()) d.reject(err);
      return;
    }
    keys.forEach((key, i) => {
      const d = batch.get(key);
      if (values[i] instanceof Error) d.reject(values[i]);
      else d.resolve(values[i]);
    });
  };

  return function load(key) {
    if (pending === null) {
      const batch = new Map();
      pending = batch;
      queueMicrotask(() => {
        pending = null;
        dispatch(batch);
      });
    }
    let d = pending.get(key);
    if (!d) {
      d = {};
      d.promise = new Promise((resolve, reject) => {
        d.resolve = resolve;
        d.reject = reject;
      });
      pending.set(key, d);
    }
    return d.promise;
  };
}

