drills.solution:
export async function assertQueryBudget(db, max, fn) {
  const queries = [];
  const off = db.onQuery((sql) => queries.push(sql));
  let result;
  try {
    result = await fn();
  } finally {
    off();
  }
  if (queries.length > max) {
    const list = queries.map((q, i) => `  ${i + 1}. ${q}`).join('\n');
    throw new Error(`query budget exceeded: ${queries.length} queries, budget ${max}\n${list}`);
  }
  return { result, queries };
}

